function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9@.]/g, ''); }
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

function parseDate(v) {
  const t = s(v); if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) { return m[1] + '-' + m[2] + '-' + m[3]; }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (m) { let y = +m[3]; if (y < 100) { y += 2000; } return y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2); }
  const d = new Date(t); return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
// one inbox = one person: key on the first email address, fall back to the investor name
function who(p) { const e = s(p.email).split(/[,;\s]+/)[0].toLowerCase(); return e ? e : 'name:' + nz(p.investor); }
function weekdaysBetween(a, b) { let n = 0; const d = new Date(a + 'T00:00:00Z'); const e = new Date(b + 'T00:00:00Z');
  while (d <= e) { const w = d.getUTCDay(); if (w !== 0 && w !== 6) { n++; } d.setUTCDate(d.getUTCDate() + 1); } return n; }

const TODAY = '2026-09-10';
const dealDay = {}, mailDay = {}, perInv = {}, names = {};
let sent = 0, undated = 0, fus = 0, first = null, last = null;
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() !== 'yes') { continue; }
  const k = who(p); names[k] = s(p.investor);
  const d = parseDate(p.date_shared);
  if (!d) { undated++; continue; }
  sent++;
  if (!first || d < first) { first = d; } if (!last || d > last) { last = d; }
  const kd = k + '|' + d;
  if (!dealDay[kd]) { dealDay[kd] = { n: 0, owners: {}, startups: [] }; }
  dealDay[kd].n++; dealDay[kd].owners[s(p.owner)] = 1; dealDay[kd].startups.push(s(p.startup));
  perInv[k] = (perInv[k] || 0) + 1;
  mailDay[kd] = (mailDay[kd] || 0) + 1;
  // follow-ups are emails too
  for (const f of ['fu1', 'fu2', 'fu3']) {
    if (/^(yes|y|true|done)$/i.test(s(p[f + '_done']))) {
      const fd = parseDate(p[f + '_date']); if (!fd) { continue; }
      fus++; mailDay[k + '|' + fd] = (mailDay[k + '|' + fd] || 0) + 1;
    }
  }
}
const pairs = Object.keys(dealDay);
const reached = Object.keys(perInv).length;
const wd = first ? weekdaysBetween(first, last) : 0;
const dist = { one: 0, two: 0, three: 0, four_plus: 0 };
let multiMailbox = 0; let worst = [];
for (const kd of pairs) {
  const x = dealDay[kd];
  if (x.n === 1) { dist.one++; } else if (x.n === 2) { dist.two++; } else if (x.n === 3) { dist.three++; } else { dist.four_plus++; }
  if (Object.keys(x.owners).length >= 2) { multiMailbox++; }
  worst.push([x.n, kd, Object.keys(x.owners).join('+'), x.startups.join(', ')]);
}
worst.sort(function (a, b) { return b[0] - a[0]; });
worst = worst.slice(0, 8).map(function (w) { const k = w[1].split('|'); return (names[k[0]] || k[0]) + ' on ' + k[1] + ': ' + w[0] + ' deals via ' + w[2] + ' (' + w[3] + ')'; });
const mailPairs = Object.keys(mailDay);
let mailTotal = 0, mailMax = 0; for (const kd of mailPairs) { mailTotal += mailDay[kd]; if (mailDay[kd] > mailMax) { mailMax = mailDay[kd]; } }
const top = Object.keys(perInv).sort(function (a, b) { return perInv[b] - perInv[a]; }).slice(0, 10)
  .map(function (k) { return (names[k] || k) + ': ' + perInv[k] + ' deals = ' + (wd ? (perInv[k] / wd).toFixed(2) : '?') + '/weekday'; });

// last 5 weekdays only
const recentStart = '2026-09-04';
let rSent = 0; const rInv = {};
for (const kd of pairs) { const d = kd.split('|')[1]; if (d >= recentStart && d <= TODAY) { rSent += dealDay[kd].n; rInv[kd.split('|')[0]] = 1; } }
const rWd = weekdaysBetween(recentStart, TODAY);

// what is queued: same inbox scheduled for several deals on one day
const qDay = {}; const qInv = {}; let queued = 0; let qFirst = null, qLast = null;
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes' || s(p.pause).toLowerCase() === 'yes') { continue; }
  const d = parseDate(p.next_due); if (!d || d <= TODAY) { continue; }
  queued++; const k = who(p); names[k] = names[k] || s(p.investor);
  const kd = k + '|' + d; qDay[kd] = (qDay[kd] || 0) + 1; qInv[k] = 1;
  if (!qFirst || d < qFirst) { qFirst = d; } if (!qLast || d > qLast) { qLast = d; }
}
const qd = { one: 0, two: 0, three: 0, four_plus: 0 }; let qMax = 0, qMaxKey = '';
for (const kd of Object.keys(qDay)) { const n = qDay[kd];
  if (n === 1) { qd.one++; } else if (n === 2) { qd.two++; } else if (n === 3) { qd.three++; } else { qd.four_plus++; }
  if (n > qMax) { qMax = n; qMaxKey = kd; } }
const qWd = qFirst ? weekdaysBetween(qFirst, qLast) : 0;
const qInvN = Object.keys(qInv).length;

return [{ json: {
  pipeline_rows: pipe.length, sent_dated: sent, sent_undated: undated, follow_ups_sent: fus,
  period: first + ' to ' + last, weekdays_in_period: wd, investors_reached: reached,
  avg_deals_per_investor_per_weekday: reached && wd ? +(sent / reached / wd).toFixed(3) : null,
  avg_deals_per_investor_on_days_they_got_one: pairs.length ? +(sent / pairs.length).toFixed(3) : null,
  investor_days: pairs.length, investor_day_distribution: dist, investor_days_from_2plus_mailboxes: multiMailbox,
  max_deals_one_investor_one_day: worst.length ? worst[0] : null, worst_days: worst,
  emails_incl_followups: { total: mailTotal, investor_days: mailPairs.length, per_active_day: mailPairs.length ? +(mailTotal / mailPairs.length).toFixed(3) : null, max_one_day: mailMax },
  last_5_weekdays: { from: recentStart, weekdays: rWd, deals: rSent, investors: Object.keys(rInv).length,
    avg_per_investor_per_weekday: Object.keys(rInv).length && rWd ? +(rSent / Object.keys(rInv).length / rWd).toFixed(3) : null },
  top_investors: top,
  queued_future: { rows: queued, inboxes: qInvN, span: qFirst + ' to ' + qLast, weekdays: qWd,
    avg_per_inbox_per_weekday: qInvN && qWd ? +(queued / qInvN / qWd).toFixed(3) : null,
    inbox_days_distribution: qd, max_one_day: qMax, max_example: (names[qMaxKey.split('|')[0]] || qMaxKey.split('|')[0]) + ' on ' + qMaxKey.split('|')[1] }
} }];
